/**
 * Proposal API (Feature 21) — typed wrapper over the existing HTTP client.
 *
 * F07 endpoints, verified against the running API:
 * - `GET /api/proposals?search=&clientId=&demandId=&status=` (newest first, no
 *   pagination; a `status=SENT` filter also excludes expired ones);
 * - `GET /api/proposals/{id}`;
 * - `POST /api/proposals` (status always starts as DRAFT, number and totals are
 *   generated by the backend);
 * - `PUT /api/proposals/{id}` (full editable state + `version`, **DRAFT only**,
 *   409 otherwise);
 * - `PATCH /api/proposals/{id}/status` ({status, version}, strict state machine,
 *   409 on an illegal transition or a stale version);
 * - `PATCH /api/proposals/{id}/deposit` (deposit only, any non-terminal status).
 *
 * The `DELETE` endpoint exists but is intentionally not exposed by this UI:
 * withdrawing a quote is the `CANCELLED` transition (Feature 21 scope).
 */

import { ApiError, api } from "@/lib/api";
import type { Proposal, ProposalStatus } from "@/types/api";

/** One line of the `ProposalLineRequest` contract. */
export interface ProposalLinePayload {
  /** Optional catalogue reference; the values below always win. */
  serviceId: string | null;
  /** Snapshot description (required, ≤ 500). */
  description: string;
  /** Snapshot unit (required, ≤ 50). */
  unit: string;
  /** numeric(14,3), strictly positive. */
  quantity: number;
  /** numeric(14,2), ≥ 0. */
  unitPrice: number;
  notes: string | null;
}

/** Body of `POST /api/proposals`. */
export interface ProposalPayload {
  clientId: string;
  demandId: string;
  title: string | null;
  validUntil: string | null;
  /** Mandatory, > 0 and never above the proposal total (service-side check). */
  requiredDeposit: number;
  notes: string | null;
  lines: ProposalLinePayload[];
}

/** Body of `PUT /api/proposals/{id}`: the editable state plus the version. */
export interface ProposalUpdatePayload extends ProposalPayload {
  version: number;
}

export interface ProposalFilters {
  search?: string;
  status?: ProposalStatus | "";
  /** Proposals of one demand (backend parameter). */
  demandId?: string | null;
}

/** List path with only the filters that are actually set. */
export function proposalsPath(filters: ProposalFilters = {}): string {
  const params = new URLSearchParams();
  const search = filters.search?.trim();
  if (search) {
    params.set("search", search);
  }
  if (filters.demandId) {
    params.set("demandId", filters.demandId);
  }
  if (filters.status) {
    params.set("status", filters.status);
  }
  const query = params.toString();
  return query ? `/api/proposals?${query}` : "/api/proposals";
}

export const proposalsApi = {
  list(filters: ProposalFilters = {}): Promise<Proposal[]> {
    return api.get<Proposal[]>(proposalsPath(filters));
  },
  get(id: string): Promise<Proposal> {
    return api.get<Proposal>(`/api/proposals/${id}`);
  },
  create(payload: ProposalPayload): Promise<Proposal> {
    return api.post<Proposal>("/api/proposals", payload);
  },
  update(id: string, payload: ProposalUpdatePayload): Promise<Proposal> {
    return api.put<Proposal>(`/api/proposals/${id}`, payload);
  },
  /** Strict state machine of Feature 07: the backend is the authority. */
  changeStatus(id: string, status: ProposalStatus, version: number): Promise<Proposal> {
    return api.patch<Proposal>(`/api/proposals/${id}/status`, { status, version });
  },
  /**
   * Deposit-only update (F07 `PATCH /{id}/deposit`, version required). The
   * backend currently applies no preparation lock; Feature 22 decides in the UI.
   */
  updateDeposit(id: string, requiredDeposit: number, version: number): Promise<Proposal> {
    return api.patch<Proposal>(`/api/proposals/${id}/deposit`, { requiredDeposit, version });
  },
};

/**
 * Transitions allowed by the F07 state machine (mirror of `ProposalService`).
 * Terminal statuses list no target at all.
 */
export const ALLOWED_TRANSITIONS: Record<ProposalStatus, readonly ProposalStatus[]> = {
  DRAFT: ["SENT", "CANCELLED"],
  SENT: ["ACCEPTED", "REFUSED", "CANCELLED", "DRAFT", "EXPIRED"],
  ACCEPTED: [],
  REFUSED: [],
  EXPIRED: [],
  CANCELLED: [],
};

export function canTransition(from: ProposalStatus, to: ProposalStatus): boolean {
  return ALLOWED_TRANSITIONS[from].includes(to);
}

export function isTerminalStatus(status: ProposalStatus): boolean {
  return ALLOWED_TRANSITIONS[status].length === 0;
}

/**
 * User-facing message for a failed proposal call. F07 answers 400/409 with a
 * generic Spring body, so the status is translated here.
 */
export function proposalErrorMessage(error: unknown): string {
  if (!(error instanceof ApiError)) {
    return "Une erreur inattendue est survenue. Réessayez.";
  }
  switch (error.status) {
    case 400:
      return "Certaines informations sont invalides. Vérifiez les champs puis réessayez.";
    case 409:
      return "Cette proposition a été modifiée entre-temps. Rechargez-la avant de réessayer.";
    case 404:
      return "Cette proposition n'existe plus.";
    case 403:
      return "Accès refusé.";
    default:
      return error.message;
  }
}
